// Junta cotizacion + criterios + solicitud y resuelve el destinatario del envio.
const q = $('Leer cotización').first().json || {};
const c = $('Leer criterios').first().json || {};
const s = $('Leer solicitud').first().json || {};
const emailSolicitante = String(c.email_solicitante || '').trim();
const emailCliente = String(s.email_cliente || '').trim();
const destinatario = emailSolicitante || emailCliente;
const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(destinatario);
const id = q.id_solicitud || c.id_solicitud || null;
const pdf = q.pdf_url || null;
const faltantes = [];
if (!id) faltantes.push('id_solicitud');
if (!pdf) faltantes.push('pdf_url');
if (!emailValido) faltantes.push('email de destinatario');
return { json: {
  id_solicitud: id,
  servicio: q.servicio || c.servicio || '',
  total_registros: q.total_registros,
  valor: q.valor, iva: q.iva, valor_total: q.valor_total,
  pdf_url: pdf,
  estado_actual: q.estado || '',
  nombre_cliente: s.nombre_cliente || c.nombre_solicitante || '',
  razon_social: c.razon_social || '',
  email_solicitante: emailSolicitante,
  email_cliente: emailCliente,
  email_destinatario: destinatario,
  cc_destinatario: 'asesor@example.com',
  datos_completos: faltantes.length === 0,
  faltantes: faltantes.join(', ')
} };

// Calcula el tamano del PDF para decidir adjunto vs link (limite ~4MB).
// OJO: n8n guarda el binario en el filesystem ('database') y expone 'bytes' numerico;
// 'fileSize' puede venir como string humana ("1 MB"). El dato fiable es 'bytes'.
const b = ($input.item.binary && $input.item.binary.data) || {};
const fromBytes = Number(b.bytes) || 0;
const fromB64 = (typeof b.data === 'string' && b.data !== 'database') ? Math.floor((b.data.length * 3) / 4) : 0;
const tamano = fromBytes || fromB64 || 0;
const LIMITE = 4 * 1024 * 1024;
return { json: { ...$json, tamano_bytes: tamano, adjuntar: tamano > 0 && tamano <= LIMITE }, binary: $input.item.binary };

// Arma el email branded CCB con el resumen de la propuesta. Dos variantes: con adjunto y solo link.
// Importante: los Code nodes no propagan el binario solos -> se pasa explicitamente.
