const nombre = d.nombre_cliente || 'estimado cliente';
const fmt = (n) => Number(n || 0).toLocaleString('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 });
const registros = Number(d.total_registros || 0).toLocaleString('es-CO');
const empresa = d.razon_social ? (' para <strong>' + d.razon_social + '</strong>') : '';
const link = d.pdf_url || '#';

const parrafoConAdjunto = '<p style="font-size:14px;color:#404e4f;margin:0 0 16px 0;line-height:1.7;">La propuesta completa (PDF) esta <strong>adjunta a este correo</strong>. Tambien podes verla online haciendo <a href="' + link + '" style="color:#004c9e;">clic aca</a>.</p>';
const parrafoSoloLink = '<p style="font-size:14px;color:#404e4f;margin:0 0 16px 0;line-height:1.7;">Podes ver y descargar la propuesta completa en el siguiente enlace:</p>'
  + '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:20px 0;"><tr><td align="center">'
  + '<a href="' + link + '" style="display:inline-block;background-color:#009CDE;color:#FFFFFF;text-decoration:none;font-size:14px;font-weight:700;padding:14px 32px;border-radius:8px;">Ver propuesta (PDF)</a>'
  + '</td></tr></table>';

const resumen = '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="border-radius:10px;overflow:hidden;border:1px solid #D9E2EC;margin:20px 0;">'
  + '<tr><td bgcolor="#001489" style="padding:10px 20px;"><p style="font-size:10px;font-weight:700;color:#009CDE;text-transform:uppercase;letter-spacing:2px;margin:0;">Resumen de la propuesta</p></td></tr>'
  + '<tr><td bgcolor="#F2F5F9" style="padding:16px 20px;">'
  + '<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Servicio:</strong> ' + (d.servicio || '-') + '</p>'
  + '<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Registros:</strong> ' + registros + '</p>'
  + '<p style="font-size:14px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Valor total:</strong> ' + fmt(d.valor_total) + '</p>'
  + '<p style="font-size:13px;color:#212120;margin:0;"><strong style="color:#001489;">Referencia:</strong> ' + (d.id_solicitud || '-') + '</p>'
  + '</td></tr></table>';

const shell = (parrafoDoc) => '<!DOCTYPE html>\n<html lang="es"><head><meta charset="UTF-8"></head>\n'
  + '<body style="margin:0;padding:0;background-color:#F2F5F9;font-family:Arial,sans-serif;">'
  + '<table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#F2F5F9"><tr><td align="center" style="padding:32px 16px;">'
  + '<table width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="#FFFFFF" style="max-width:600px;border-radius:12px;overflow:hidden;box-shadow:0 6px 32px rgba(0,20,137,0.14);">'
  + '<tr><td bgcolor="#001489" align="center" style="padding:32px 40px 28px 40px;background-image:linear-gradient(135deg,#001489 0%,#014392 60%,#009CDE 100%);">'
  + '<img src="https://prod.camarabaq.org.co/wp-content/uploads/2022/07/Logo-CCB-Blanco.png" alt="CamaraBAQ" width="140" style="max-width:140px;margin:0 auto 14px auto;" />'
  + '<p style="font-size:11px;font-weight:600;color:rgba(255,255,255,0.65);text-transform:uppercase;letter-spacing:3px;margin:0;">Servicios de Informacion</p>'
  + '</td></tr>'
  + '<tr><td bgcolor="#009CDE" align="center" style="padding:11px 32px;"><p style="font-size:12px;font-weight:700;color:#FFFFFF;text-transform:uppercase;letter-spacing:2px;margin:0;">Propuesta comercial</p></td></tr>'
  + '<tr><td bgcolor="#FFFFFF" style="padding:32px 40px 24px 40px;">'
  + '<p style="font-size:14px;color:#404e4f;margin:0 0 16px 0;line-height:1.7;">Hola ' + nombre + ',<br><br>Te compartimos la propuesta comercial preparada' + empresa + '.</p>'
